  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  SYSTEM_ADMIN\n  INSTITUTION_OWNER\n  STAFF_ADMIN\n  TEACHER\n}\n\nenum InstitutionType {\n  SCHOOL\n  COLLEGE\n  UNIVERSITY\n}\n\nenum SubjectType {\n  THEORY\n  LAB\n}\n\nenum RoomType {\n  CLASSROOM\n  LAB\n}\n\nenum TimetableStatus {\n  DRAFT\n  LOCKED\n}\n\nmodel User {\n  id       String  @id @default(uuid())\n  name     String\n  email    String  @unique\n  password String\n  role     Role\n  isActive Boolean @default(true)\n\n  staffs Staff[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Institution {\n  id      String          @id @default(uuid())\n  name    String\n  type    InstitutionType\n  ownerId String\n\n  campuses                    Campus[]\n  staffs                      Staff[]\n  timetableGenerationSettings TimetableGenerationSetting[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Campus {\n  id            String @id @default(uuid())\n  institutionId String\n  name          String\n  location      String\n\n  institution Institution @relation(fields: [institutionId], references: [id], onDelete: Cascade)\n\n  departments      Department[]\n  teachers         Teacher[]\n  rooms            Room[]\n  timeSlots        TimeSlot[]\n  workingDays      WorkingDay[]\n  holidays         Holiday[]\n  academicLevels   AcademicLevel[]\n  staffs           Staff[]\n  staffCampusLinks StaffCampus[]\n\n  createdAt DateTime @default(now())\n}\n\nmodel AcademicLevel {\n  id       String @id @default(uuid())\n  campusId String\n  name     String\n\n  campus   Campus    @relation(fields: [campusId], references: [id])\n  sections Section[]\n}\n\nmodel Section {\n  id              String  @id @default(uuid())\n  academicLevelId String\n  name            String\n  sectionCode     String?\n\n  academicLevel   AcademicLevel    @relation(fields: [academicLevelId], references: [id])\n  sectionSubjects SectionSubject[]\n}\n\nmodel Department {\n  id       String    @id @default(uuid())\n  campusId String\n  name     String\n  campus   Campus    @relation(fields: [campusId], references: [id])\n  subjects Subject[]\n}\n\nmodel Subject {\n  id           String      @id @default(uuid())\n  departmentId String\n  name         String\n  type         SubjectType\n  weeklyHours  Int\n\n  department      Department       @relation(fields: [departmentId], references: [id])\n  teacherSubjects TeacherSubject[]\n  sectionSubjects SectionSubject[]\n  timetables      Timetable[]\n}\n\nmodel SectionSubject {\n  id        String @id @default(uuid())\n  sectionId String\n  subjectId String\n\n  section Section @relation(fields: [sectionId], references: [id], onDelete: Cascade)\n  subject Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n\n  @@unique([sectionId, subjectId])\n}\n\nmodel Teacher {\n  id         String  @id @default(uuid())\n  name       String\n  email      String\n  phone      String?\n  campusId   String\n  maxPerDay  Int\n  maxPerWeek Int\n\n  campus Campus @relation(fields: [campusId], references: [id])\n\n  teacherSubjects     TeacherSubject[]\n  teacherAvailability TeacherAvailability[]\n  timetables          Timetable[]\n}\n\nmodel Staff {\n  id            String  @id @default(uuid())\n  userId        String\n  institutionId String\n  campusId      String?\n\n  user        User          @relation(fields: [userId], references: [id])\n  institution Institution   @relation(fields: [institutionId], references: [id])\n  campus      Campus?       @relation(fields: [campusId], references: [id])\n  campusLinks StaffCampus[]\n\n  createdAt DateTime @default(now())\n}\n\nmodel StaffCampus {\n  id       String @id @default(uuid())\n  staffId  String\n  campusId String\n\n  staff  Staff  @relation(fields: [staffId], references: [id], onDelete: Cascade)\n  campus Campus @relation(fields: [campusId], references: [id], onDelete: Cascade)\n\n  @@unique([staffId, campusId])\n}\n\nmodel TeacherAvailability {\n  id          String  @id @default(uuid())\n  teacherId   String\n  dayId       String\n  timeSlotId  String\n  isAvailable Boolean @default(true)\n\n  teacher  Teacher    @relation(fields: [teacherId], references: [id])\n  day      WorkingDay @relation(fields: [dayId], references: [id])\n  timeSlot TimeSlot   @relation(fields: [timeSlotId], references: [id])\n\n  @@unique([teacherId, dayId, timeSlotId])\n}\n\nmodel Room {\n  id       String   @id @default(uuid())\n  campusId String\n  name     String\n  type     RoomType\n  capacity Int\n\n  campus     Campus      @relation(fields: [campusId], references: [id])\n  timetables Timetable[]\n}\n\nmodel TimeSlot {\n  id        String  @id @default(uuid())\n  campusId  String\n  startTime String\n  endTime   String\n  isBreak   Boolean @default(false)\n\n  teacherAvailability TeacherAvailability[]\n  timetables          Timetable[]\n\n  campus Campus @relation(fields: [campusId], references: [id])\n}\n\nmodel WorkingDay {\n  id       String @id @default(uuid())\n  campusId String\n  dayName  String\n\n  teacherAvailability TeacherAvailability[]\n  timetables          Timetable[]\n\n  campus Campus @relation(fields: [campusId], references: [id])\n}\n\nmodel Holiday {\n  id       String   @id @default(uuid())\n  campusId String\n  date     DateTime\n  name     String\n\n  campus Campus @relation(fields: [campusId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([campusId, date])\n}\n\nmodel Timetable {\n  id              String          @id @default(uuid())\n  campusId        String\n  academicLevelId String\n  sectionId       String\n  subjectId       String\n  teacherId       String\n  roomId          String\n  dayId           String\n  timeSlotId      String\n  status          TimetableStatus\n\n  subject  Subject    @relation(fields: [subjectId], references: [id])\n  teacher  Teacher    @relation(fields: [teacherId], references: [id])\n  room     Room       @relation(fields: [roomId], references: [id])\n  day      WorkingDay @relation(fields: [dayId], references: [id])\n  timeSlot TimeSlot   @relation(fields: [timeSlotId], references: [id])\n\n  createdAt DateTime @default(now())\n}\n\nmodel TimetableGenerationSetting {\n  id                      String          @id @default(uuid())\n  institutionId           String\n  institutionType         InstitutionType\n  generationScope         String          @default(\"CLASS\")\n  changeRoomEveryLecture  Boolean         @default(false)\n  selectedClassName       String?\n  selectedAcademicLevelId String?\n  selectedSectionId       String?\n  subjectWeeklyLectures   Json?\n  updatedByUserId         String?\n\n  institution Institution @relation(fields: [institutionId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([institutionId, institutionType])\n}\n\nmodel TeacherSubject {\n  id        String @id @default(uuid())\n  teacherId String\n  subjectId String\n\n  teacher Teacher @relation(fields: [teacherId], references: [id])\n  subject Subject @relation(fields: [subjectId], references: [id])\n\n  @@unique([teacherId, subjectId])\n}\n",
